head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gLdMktTp = js_market;
scwin.gEmpNo = js_emp_no;
scwin.gAcptNo;
scwin.gIsurCd;
scwin.vScrenID = "ULDSTF35002.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    if (scwin.gLdMktTp == '1' || scwin.gLdMktTp == '2' || scwin.gLdMktTp == '4' || scwin.gLdMktTp == '6') {
        rdo_MKT_ID.setDisabled(true);
    } else {
        $c.stf.setObjectValue(rdo_MKT_ID, '9');
    }
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate.setValue(vCurDate);
    edt_EDate.setValue(vCurDate);
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
    $c.stf.setObjectValue(rdo_MKT_ID, js_market);
    $c.stf.setObjectValue(rdo_REGULSS_YN, "");
};
scwin.fn_Search = function() {
    if (scwin.dateCheck() == false) {
        return;
    }
    var url = "/AtsContactInfo.do?method=listHaltSndrcv" + "&FROM_DATE=" + edt_SDate.getValue() + "&TO_DATE=" + edt_EDate.getValue() + "&LD_MKT_TP=" + $c.stf.getObjectValue(rdo_MKT_ID) + "&REGULSS_YN=" + $c.stf.getObjectValue(rdo_REGULSS_YN) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Grid.DataID = encodeURI(url);
    dts_Grid.reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.dateCheck = function() {
    if (parseInt(edt_SDate.getValue(), '10') > parseInt(edt_EDate.getValue(), '10')) {
        $c.win.alert("[조회기간 시작일은 종료일보다 작아야 합니다.]다시 입력해주세요");
        edt_SDate.setValue($c.ut.cGetToday("yyyymmdd"));
        edt_EDate.setValue($c.ut.cGetToday("yyyymmdd"));
        return false;
    }
};
scwin.getChkValue = function(obj) {
    //return (obj.checked) ? "Y" : "N";
    if (obj.checked == true) {
        return obj.getValue();
    } else {
        return "0";
    }
};
scwin.setChkValue = function(obj, booleanVal) {
    //return (obj.checked) ? "Y" : "N";
    obj.setValue(booleanVal);
};
scwin.fn_save = function() {
    scwin.fn_SetHeader();
    for (var i = 1, k = 0; i <= dts_Grid.getTotalRow(); i++) {
        if (dts_Grid.getRowStatus(i) != 0) {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
            // ********************************************************************

            k++;
            dts_UpdateList.insertRow();
            dts_UpdateList.setCellData(k, "ACPT_NO", dts_Grid.getCellData(i, "SND_MSG_SEQ"));
            dts_UpdateList.setCellData(k, "ISU_CD", dts_Grid.getCellData(i, "ISU_CD")); /*ORG SRC: dts_UpdateList.NameString(k, "CABLE_NOTI_YN") = dts_Grid.NameString(i, "CABLE_NOTI_YN") == "수기입력" ? "" : dts_Grid.NameString(i, "CABLE_NOTI_YN");*/ X = dts_Grid.getCellData(i, "CABLE_NOTI_YN") == "수기입력" ? "" : dts_Grid.getCellData(i, "CABLE_NOTI_YN");
            dts_UpdateList.setCellData(k, "CABLE_CSLT_NM", dts_Grid.getCellData(i, "CABLE_CSLT_NM"));
            dts_UpdateList.setCellData(k, "REG_EMP_NO", scwin.gEmpNo);
        }
    }
    if (k > 0) {
        if (!window.confirm($c.stf.getMessageParam("MSG-A006", '총 ' + k + '건을 저장'))) return;
        procJob = "거래정지 송수신 유선통보 수정";
        trs_save.Action = "/AtsContactInfo.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=updateHaltSndrcvCableNoti";
        trs_save.KeyName = "toinb_dataid4";
        trs_save.KeyValue = "JSP(I:pInput=dts_UpdateList)";
        trs_save.Post();
    } else {
        $c.win.alert("변경된 데이터가 없습니다.");
    }
};
scwin.fn_SetHeader = function() {
    dts_UpdateList.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=HALT_SNDRCV_INOUT";
    dts_UpdateList.reset();
};


// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gAcptNo = dts_Grid.getCellData(eval(obj), "ACPT_NO");
    scwin.gIsurCd = dts_Grid.getCellData(eval(obj), "ISUR_CD");
};
scwin.icn_SCal_onclick = function() {
    popUpCalendar4(edt_SDate, 1);
};
scwin.icn_ECal_onclick = function() {
    popUpCalendar4(edt_EDate, 2);
};
scwin.edt_SDate_OnLastChar = function(ch) {
    afterPopUpCalendar(1); //if(시작일>종료일) 종료일=시작일;

};
scwin.edt_EDate_OnLastChar = function(ch) {
    afterPopUpCalendar(2); //if(시작일>종료일) 시작일=종료일;

};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.dts_Grid_OnFail = function() {
    $c.stf.alert_error(dts_Grid);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_Grid_OnLoadError = function() {
    $c.stf.alert_error(dts_Grid);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    if (rowcount <= 0) {
        dts_Grid.removeAll();
    }
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리

};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.fn_setContnId(row);
    if (colid == 'DOC_TITLE') {
        if (scwin.gAcptNo != '') {
            $c.stf.fn_OpenDisclViewer(scwin.gAcptNo, "R", scwin.vScrenID);
        }
    } else if (colid == "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
};
scwin.rdo_MKT_ID_OnSelChange = function() {

};
scwin.trs_save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", procJob));
};
scwin.trs_save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001", procJob));
    scwin.fn_Search();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    $c.data.downloadGridViewExcel(grd_Grid, "거래정지 송수신 내역", "", "2");
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();
    scwin.fn_Search();
};
scwin.btn_Save_onclick = function() {
    scwin.fn_save();
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
